mutants.replacement:
bookmarks
      .map((bookmark: string) => {
        if (bookmark.endsWith('/')) return createDummyFolderNodeDef(bookmark)

        const parts = bookmark.split('/')
        const name = parts.pop() ?? ''
        const category = parts.join('/')
        const srcNodeDef = nodeDefStore.getNodeDefByName(name)
        if (!srcNodeDef) return null
        const nodeDef = clone(srcNodeDef)
        nodeDef.category = category
        return nodeDef
      })

initializePromise &&= (async () => {
      try {
        userConfig.value = await api.getUserConfig()
        currentUserId.value = localStorage['Comfy.userId']
      } catch (err) {
        initializePromise = null
        throw err
      }
    })()
